def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        # Parse one field
        if i == len(line):
            # End of line - we've parsed all fields
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote or the end quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - represents one quote character
                        field.append('"')
                        i += 2
                    else:
                        # End quote
                        i += 1
                        # Check what follows
                        if i == len(line):
                            # End of line - valid
                            fields.append(''.join(field))
                            break
                        elif line[i] == ',':
                            # Comma follows - valid
                            fields.append(''.join(field))
                            i += 1
                            break
                        else:
                            # Invalid character after closing quote
                            return None
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without finding closing quote
                return None
        else:
            # Unquoted field
            field = []
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Double quote in unquoted field is not allowed
                    return None
                field.append(line[i])
                i += 1

            fields.append(''.join(field))

            # Move past comma if present
            if i < len(line) and line[i] == ',':
                i += 1

    return fields

